#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n;
    if (!(cin >> m >> n)) return 0;
    vector<string> grid(m);
    for (int i = 0; i < m; ++i) cin >> grid[i];   // 每行一个字符串

    vector<vector<bool>> seen(m, vector<bool>(n, false));
    int blocks = 0;
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] != '1' || seen[i][j]) continue;
            ++blocks;
            queue<pair<int, int>> q;
            q.push({i, j});
            seen[i][j] = true;
            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                for (int k = 0; k < 4; ++k) {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                        grid[nx][ny] == '1' && !seen[nx][ny]) {
                        seen[nx][ny] = true;
                        q.push({nx, ny});
                    }
                }
            }
        }
    }
    cout << blocks << "\n";
    return 0;
}

