#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v) : val(v), next(nullptr) {}
};

ListNode* build(const vector<int>& vals) {
    ListNode dummy(0);                 // 哨兵节点，尾插
    ListNode* cur = &dummy;
    for (int v : vals) {
        cur->next = new ListNode(v);
        cur = cur->next;
    }
    return dummy.next;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> vals(n);
    for (int i = 0; i < n; ++i) cin >> vals[i];
    ListNode* head = build(vals);

    ListNode* prev = nullptr;          // 反转
    while (head) {
        ListNode* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }

    vector<int> out;
    while (prev) {
        out.push_back(prev->val);
        prev = prev->next;
    }
    for (size_t i = 0; i < out.size(); ++i) {
        if (i) cout << " ";
        cout << out[i];
    }
    cout << "\n";
    return 0;
}

