#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    int s;
    cin >> s;
    const long long INF = (long long)4e18;
    vector<long long> dist(n + 1, INF);
    dist[s] = 0;
    priority_queue<pair<long long, int>,
                   vector<pair<long long, int>>, greater<>> pq;   // (距离, 节点)
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;     // 跳过过期状态
        for (auto [v, w] : g[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << " ";
        if (dist[i] == INF) cout << "inf";
        else cout << dist[i];
    }
    cout << "\n";
    return 0;
}

