#include <bits/stdc++.h>
using namespace std;

int find(vector<int>& parent, int x) {
    while (parent[x] != x) {           // 路径压缩写成循环
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> parent(n + 1);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    int merged = 0;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        int ru = find(parent, u), rv = find(parent, v);
        if (ru != rv) {
            parent[ru] = rv;
            ++merged;
        }
    }
    cout << n - merged << "\n";        // 连通块个数
    return 0;
}

